/* shadcn's chat: a bg-muted prompt bubble with a 1 px --border hairline and the 10 px --radius
   (rounded-lg), cards outlined like <Card> (a hairline, next to no fill, no shadow),
   --muted-foreground for secondary text, and links as shadcn draws them: the foreground, underlined.
   Only cmux.agentPane.style/1 tokens (schemas/agent-pane/style-tokens.json), on :root: paint, so
   nothing in the transcript moves when this applies or reloads. Every color is made from the
   theme's own (--agent-text, --agent-page-bg, --agent-danger), so it reads over shadcn and shadcn
   Dark alike and over any theme of your own. The mixes land on shadcn's neutral tokens:
   text at 10% is --border (#e5e5e5 over white, white-at-10% over #0a0a0a), text at 62% is
   --muted-foreground (#676767 / #9f9f9f, shadcn's #737373 / #a1a1a1 held to 4.5:1 on the fills). */
:root {
  --cv-user-bubble-tint: color-mix(in srgb, var(--agent-text) 5%, transparent);
  --cv-user-bubble-edge: color-mix(in srgb, var(--agent-text) 10%, transparent);
  --cv-user-bubble-radius: 10px;
  --cv-card-fill: color-mix(in srgb, var(--agent-text) 2.5%, transparent);
  --cv-card-ring: color-mix(in srgb, var(--agent-text) 10%, transparent);
  --cv-text-muted: color-mix(in srgb, var(--agent-text) 62%, transparent);
  --cv-text-dim: color-mix(in srgb, var(--agent-text) 58%, transparent);
  --cv-link: var(--agent-text);
  --agent-link: var(--agent-text);

  /* Pending (cmux #46490): the prompt's text on the muted bubble, the foreground. */
  --cv-user-bubble-text: var(--agent-text);

  /* Pending (cmux #46846): every page-drawn menu and popover as shadcn's DropdownMenuContent and
     ContextMenuContent: rounded-md (8 px), p-1, bg-popover with a 1 px border and shadow-md;
     items rounded-sm (6 px) at px-2 py-1.5 text-sm (32 px rows) with bg-accent on focus;
     DropdownMenuLabel text-sm font-medium in the foreground; DropdownMenuSeparator -mx-1 my-1
     bg-border (edge to edge); DropdownMenuShortcut text-xs muted; data-[disabled]:opacity-50;
     variant="destructive" in --destructive (15% toward the text, so it holds 4.5:1 on the hover
     fill); a submenu flush beside its row, its first item level with the one that opened it
     (Radix's alignOffset -5). --menu-shadow is Tailwind's shadow-md, black at 10% in both schemes
     as shadcn draws it. */
  --menu-radius: 8px;
  --menu-padding: 4px;
  --menu-fill: color-mix(in srgb, var(--agent-text) 3%, var(--agent-page-bg));
  --menu-border: color-mix(in srgb, var(--agent-text) 10%, transparent);
  --menu-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --menu-row-height: 32px;
  --menu-hover-fill: color-mix(in srgb, var(--agent-text) 8%, transparent);
  --menu-hover-radius: 6px;
  --menu-separator: color-mix(in srgb, var(--agent-text) 10%, transparent);
  --menu-separator-inset: 0px;
  --menu-label-color: var(--agent-text);
  --menu-label-weight: 500;
  --menu-label-size: var(--text-control);
  --menu-shortcut-color: color-mix(in srgb, var(--agent-text) 62%, transparent);
  --menu-subtitle-color: color-mix(in srgb, var(--agent-text) 62%, transparent);
  --menu-destructive: color-mix(in srgb, var(--agent-danger) 85%, var(--agent-text));
  --menu-disabled-opacity: 0.5;
  --menu-submenu-offset: 0px;
  --menu-submenu-align-offset: -5px;
}

